package com.primehr.performancemanagement.application;
import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.performancemanagement.api.PerformanceInterventionDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service@Transactional public class PerformanceInterventionServiceImpl implements PerformanceInterventionService{
 private final PerformanceInterventionRuleRepository rules;private final PerformanceInterventionRepository interventions;private final PerformanceInterventionCheckpointRepository checkpoints;private final PerformanceRatingCaseRepository ratingCases;private final PerformanceRatingActionRepository actions;private final PrimeHrAuditService audit;
 public PerformanceInterventionServiceImpl(PerformanceInterventionRuleRepository r,PerformanceInterventionRepository i,PerformanceInterventionCheckpointRepository c,PerformanceRatingCaseRepository rc,PerformanceRatingActionRepository a,PrimeHrAuditService au){rules=r;interventions=i;checkpoints=c;ratingCases=rc;actions=a;audit=au;}
 @Override public RuleResponse createRule(String agency,RuleInput in,String actor,String correlation){var existing=rules.findByAgencyIdAndPolicyVersionIdAndRatingScaleVersionIdAndRatingBandId(agency,in.policyVersionId(),in.ratingScaleVersionId(),in.ratingBandId());if(existing.isPresent())return rule(existing.get());PerformanceInterventionRule value=rules.saveAndFlush(new PerformanceInterventionRule(agency,in.policyVersionId(),in.ratingScaleVersionId(),in.ratingBandId(),in.action(),in.employeeMessage(),actor,Instant.now()));audit.record(agency,"CREATE_PERFORMANCE_INTERVENTION_RULE","SPMS_INTERVENTION_RULE",value.getId(),1,value.getVersion(),null,rule(value),null,correlation);return rule(value);}
 @Override@Transactional(readOnly=true)public List<RuleResponse>rules(String agency){return rules.findByAgencyIdOrderByCreatedAtAsc(agency).stream().map(this::rule).toList();}
 @Override public void evaluate(String agency,PerformanceFinalRating finalRating,String actor,String correlation){if(interventions.findByAgencyIdAndFinalRatingId(agency,finalRating.getId()).isPresent())return;PerformanceRatingCase rating=rating(agency,finalRating.getRatingCaseId());var configured=rules.findByAgencyIdAndPolicyVersionIdAndRatingScaleVersionIdAndRatingBandId(agency,rating.getPolicyVersionId(),rating.getRatingScaleVersionId(),finalRating.getRatingBandId());if(configured.isEmpty()||configured.get().getAction()==PerformanceInterventionRule.Action.NONE)return;PerformanceIntervention value=interventions.saveAndFlush(new PerformanceIntervention(agency,finalRating.getId(),rating.getId(),configured.get().getId(),rating.getOwnerEmployeeNo(),configured.get().getAction()));audit.record(agency,"EVALUATE_PERFORMANCE_INTERVENTION","SPMS_PERFORMANCE_INTERVENTION",value.getId(),1,value.getVersion(),null,response(agency,value),null,correlation);}
 @Override@Transactional(readOnly=true)public List<InterventionResponse>list(String agency,String actor,PermissionDataScope scope){boolean privateNotes=scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.ASSIGNED_RECORDS;return interventions.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(x->visible(x,actor,scope)).map(x->response(agency,x,privateNotes)).toList();}
 @Override public InterventionResponse issue(String agency,String id,IssueInput in,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention value=intervention(agency,id);manage(value,actor,scope);if(prior(value,in.idempotencyKey()))return response(agency,value);if(value.getAction()==PerformanceInterventionRule.Action.ALERT)throw new IllegalStateException("An alert does not create an improvement plan");check(value.getVersion(),in.recordVersion());value.issue(in.objectives(),in.supportPlan(),in.accountableEmployeeNo(),in.startsOn(),in.endsOn(),actor,Instant.now());value=interventions.saveAndFlush(value);record(agency,value.getRatingCaseId(),id,"ISSUE_INTERVENTION",in.idempotencyKey(),actor,null);return audited(agency,value,"ISSUE_PERFORMANCE_INTERVENTION",correlation);}
 @Override public InterventionResponse acknowledge(String agency,String id,AcknowledgeInput in,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention value=intervention(agency,id);if(!value.getEmployeeNo().equalsIgnoreCase(actor)||scope!=PermissionDataScope.OWN_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the subject employee may acknowledge this intervention");if(prior(value,in.idempotencyKey()))return response(agency,value,false);check(value.getVersion(),in.recordVersion());value.acknowledge(actor,in.response(),Instant.now());value=interventions.saveAndFlush(value);record(agency,value.getRatingCaseId(),id,"ACKNOWLEDGE_INTERVENTION",in.idempotencyKey(),actor,null);InterventionResponse after=response(agency,value,false);audit.record(agency,"ACKNOWLEDGE_PERFORMANCE_INTERVENTION","SPMS_PERFORMANCE_INTERVENTION",value.getId(),1,value.getVersion(),null,after,null,correlation);return after;}
 @Override public InterventionResponse transition(String agency,String id,LifecycleInput in,String transition,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention value=intervention(agency,id);manage(value,actor,scope);if(prior(value,in.idempotencyKey()))return response(agency,value);check(value.getVersion(),in.recordVersion());switch(transition){case"start"->value.start();case"complete"->value.complete(Instant.now());case"close"->value.close(in.reason(),Instant.now());default->throw new IllegalArgumentException("Unsupported intervention transition");}value=interventions.saveAndFlush(value);record(agency,value.getRatingCaseId(),id,"INTERVENTION_"+transition.toUpperCase(Locale.ROOT),in.idempotencyKey(),actor,in.reason());return audited(agency,value,"TRANSITION_PERFORMANCE_INTERVENTION",correlation);}
 @Override public InterventionResponse addCheckpoint(String agency,String id,CheckpointInput in,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention value=intervention(agency,id);manage(value,actor,scope);if(prior(value,in.idempotencyKey()))return response(agency,value);check(value.getVersion(),in.interventionRecordVersion());if(value.getStartsOn()==null||in.dueOn().isBefore(value.getStartsOn())||in.dueOn().isAfter(value.getEndsOn()))throw new IllegalArgumentException("Checkpoint must fall within the intervention date range");PerformanceInterventionCheckpoint point=checkpoints.saveAndFlush(new PerformanceInterventionCheckpoint(agency,id,in.dueOn(),in.objective()));record(agency,value.getRatingCaseId(),point.getId(),"ADD_INTERVENTION_CHECKPOINT",in.idempotencyKey(),actor,null);return audited(agency,value,"ADD_PERFORMANCE_INTERVENTION_CHECKPOINT",correlation);}
 @Override public InterventionResponse completeCheckpoint(String agency,String id,String checkpointId,CheckpointComplete in,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention value=intervention(agency,id);manage(value,actor,scope);if(prior(value,in.idempotencyKey()))return response(agency,value);PerformanceInterventionCheckpoint point=checkpoints.findByIdAndAgencyId(checkpointId,agency).orElseThrow(()->new ResourceNotFoundException("Intervention checkpoint not found"));if(!point.getInterventionId().equals(id))throw new IllegalArgumentException("Checkpoint does not belong to intervention");check(point.getVersion(),in.recordVersion());point.complete(in.progressNote(),in.employeeVisibleFeedback(),in.privatePmtNote(),actor,Instant.now());checkpoints.saveAndFlush(point);record(agency,value.getRatingCaseId(),point.getId(),"COMPLETE_INTERVENTION_CHECKPOINT",in.idempotencyKey(),actor,null);return audited(agency,value,"COMPLETE_PERFORMANCE_INTERVENTION_CHECKPOINT",correlation);}
 private InterventionResponse audited(String agency,PerformanceIntervention x,String action,String correlation){InterventionResponse after=response(agency,x);audit.record(agency,action,"SPMS_PERFORMANCE_INTERVENTION",x.getId(),1,x.getVersion(),null,after,null,correlation);return after;}private boolean prior(PerformanceIntervention x,String key){return actions.findByAgencyIdAndRatingCaseIdAndRequestKey(x.getAgencyId(),x.getRatingCaseId(),key).isPresent();}private void record(String a,String c,String subject,String type,String key,String actor,String reason){actions.save(new PerformanceRatingAction(a,c,subject,type,key,actor,reason,Instant.now()));}
 private boolean visible(PerformanceIntervention x,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.OWN_RECORDS&&x.getEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&actor.equalsIgnoreCase(x.getAccountableEmployeeNo());}private void manage(PerformanceIntervention x,String actor,PermissionDataScope scope){if(scope!=PermissionDataScope.AGENCY_WIDE&&!(scope==PermissionDataScope.ASSIGNED_RECORDS&&actor.equalsIgnoreCase(x.getAccountableEmployeeNo())))throw new AccessDeniedException("Intervention is outside the permitted scope");}private PerformanceIntervention intervention(String a,String id){return interventions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance intervention not found"));}private PerformanceRatingCase rating(String a,String id){return ratingCases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance rating case not found"));}private RuleResponse rule(PerformanceInterventionRule x){return new RuleResponse(x.getId(),x.getPolicyVersionId(),x.getRatingScaleVersionId(),x.getRatingBandId(),x.getAction().name(),x.getEmployeeMessage(),x.getCreatedByRule(),x.getCreatedAtRule(),x.getVersion());}private InterventionResponse response(String a,PerformanceIntervention x){return response(a,x,true);}private InterventionResponse response(String a,PerformanceIntervention x,boolean privateNotes){List<CheckpointResponse> points=checkpoints.findByAgencyIdAndInterventionIdOrderByDueOnAsc(a,x.getId()).stream().map(p->new CheckpointResponse(p.getId(),p.getDueOn(),p.getObjective(),p.getProgressNote(),p.getEmployeeVisibleFeedback(),privateNotes?p.getPrivatePmtNote():null,p.getStatus().name(),p.getCompletedBy(),p.getCompletedAt(),p.getVersion())).toList();return new InterventionResponse(x.getId(),x.getFinalRatingId(),x.getRatingCaseId(),x.getRuleId(),x.getEmployeeNo(),x.getAction().name(),x.getStatus().name(),x.getObjectives(),x.getSupportPlan(),x.getAccountableEmployeeNo(),x.getStartsOn(),x.getEndsOn(),x.getEmployeeResponse(),x.getIssuedBy(),x.getIssuedAt(),x.getAcknowledgedAt(),x.getCompletedAt(),x.getClosedAt(),x.getClosureReason(),x.getVersion(),points);}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}
}
